write(
    "packages/backend/agent-task/src/lib/application/create-agent-task.ts",
    r'''
    import { randomUUID } from 'node:crypto';

    import {
      agentTaskExecutionRequestedSchema,
      type AgentTaskExecutionRequested,
    } from '@agentic-webapp/contracts';

    import {
      createAgentTask,
      type AgentTask,
    } from '../domain/agent-task';
    import type { AgentTaskRepository } from './agent-task-repository';

    export interface CreateAgentTaskCommand {
      readonly actorId: string;
      readonly title: string;
      readonly prompt: string;
      readonly correlationId?: string;
    }

    export interface AgentTaskDependencies {
      readonly createId: () => string;
      readonly now: () => Date;
    }

    const defaultDependencies: AgentTaskDependencies = {
      createId: randomUUID,
      now: () => new Date(),
    };

    export class CreateAgentTask {
      public constructor(
        private readonly repository: AgentTaskRepository,
        private readonly dependencies: AgentTaskDependencies = defaultDependencies,
      ) {}

      public async execute(command: CreateAgentTaskCommand): Promise<AgentTask> {
        const createdAt = this.dependencies.now();
        const task = createAgentTask({
          id: this.dependencies.createId(),
          ownerId: command.actorId,
          title: command.title,
          prompt: command.prompt,
          correlationId: command.correlationId ?? this.dependencies.createId(),
          createdAt,
        });
        const executionRequested: AgentTaskExecutionRequested =
          agentTaskExecutionRequestedSchema.parse({
            version: 1,
            taskId: task.id,
            actorId: task.ownerId,
            prompt: task.prompt,
            correlationId: task.correlationId,
            occurredAt: task.createdAt.toISOString(),
          });

        await this.repository.create(task, executionRequested);
        return task;
      }
    }
    ''',
)
write(
    "packages/backend/agent-task/src/lib/application/get-agent-task.ts",
    r'''
    import type { AgentTask } from '../domain/agent-task';
    import type { AgentTaskRepository } from './agent-task-repository';

    export class AgentTaskNotFoundError extends Error {
      public constructor(id: string) {
        super(`Agent task ${id} was not found.`);
        this.name = 'AgentTaskNotFoundError';
      }
    }

    export class AgentTaskForbiddenError extends Error {
      public constructor() {
        super('The actor cannot access this agent task.');
        this.name = 'AgentTaskForbiddenError';
      }
    }

    export class GetAgentTask {
      public constructor(private readonly repository: AgentTaskRepository) {}

      public async execute(id: string, actorId: string): Promise<AgentTask> {
        const task = await this.repository.findById(id);
        if (!task) {
          throw new AgentTaskNotFoundError(id);
        }
        if (task.ownerId !== actorId) {
          throw new AgentTaskForbiddenError();
        }
        return task;
      }
    }
    ''',
)
